{
  "findings": [
    {
      "check_id": "CKV_AWS_261",
      "title": "Ensure HTTP HTTPS Target group defines Healthcheck",
      "resource": "aws_lb_target_group.pass",
      "severity": "MEDIUM",
      "explanation": "The target group does not define a health check, which is necessary to ensure the availability and proper functioning of the targets."
    }
  ],
  "patched_code": "resource \"aws_lb_target_group\" \"pass\" {\n  name        = \"tf-example-lb-alb-tg\"\n  target_type = \"alb\"\n  port        = 80\n  protocol    = \"TCP\"\n  vpc_id      = aws_vpc.main.id\n\n  health_check {\n    protocol = \"TCP\"\n    port     = \"traffic-port\"\n  }\n}\n",
  "fix_summary": "Added a health check block to the target group to ensure proper monitoring of target availability and functionality."
}
